WITH page_returns AS (SELECT wp.wp_web_page_sk, wp.wp_url, wp.wp_web_page_id, wp.wp_customer_sk, AVG(wr.wr_return_amt_inc_tax) AS avg_return_amt_inc_tax, COUNT(*) AS returns_cnt, MAX(wr.wr_return_quantity) AS max_qty FROM web_page wp JOIN web_returns wr ON wr.wr_web_page_sk = wp.wp_web_page_sk GROUP BY wp.wp_web_page_sk, wp.wp_url, wp.wp_web_page_id, wp.wp_customer_sk) SELECT pr.wp_web_page_id, pr.wp_url, c.c_customer_id, pr.avg_return_amt_inc_tax, pr.returns_cnt, pr.max_qty, CASE WHEN pr.max_qty > 5 THEN 'Large' ELSE 'Small' END AS qty_category, ROW_NUMBER() OVER (PARTITION BY pr.max_qty ORDER BY pr.avg_return_amt_inc_tax DESC) AS rank_by_qty, COALESCE(sr_agg.store_net_loss, 0) AS store_loss FROM page_returns pr JOIN customer c ON pr.wp_customer_sk = c.c_customer_sk LEFT JOIN (SELECT sr.sr_customer_sk, SUM(sr.sr_net_loss) AS store_net_loss FROM store_returns sr GROUP BY sr.sr_customer_sk) sr_agg ON sr_agg.sr_customer_sk = c.c_customer_sk WHERE pr.avg_return_amt_inc_tax BETWEEN 50 AND 400 AND pr.returns_cnt > 2 ORDER BY pr.max_qty DESC, pr.avg_return_amt_inc_tax ASC LIMIT 30
